     "summary": "8月27日，外交部发言人林剑主持例行记者会。法新社记者提问，美国总统特朗普周三就美国国内电力电网中的外国制造设备宣布“国家紧急状态”。特朗普还称，日益增长的电力需求使美国电力系统成为敌对政府的目标。中方对此有何评论？ 林剑表示，中方一贯反对泛化国家安全概念、打压别国企业的做法，希望美方为各国企业经营提供公平、公正、非歧视的环境。（文章来源：澎湃新闻）",
